def enqueue(queue, task, tags=[]):
    if not tags:
        return None
    queue.append({"task": task, "tags": tags})
    return None

from asyncio import gather, run, iscoroutinefunction, wait, sleep, create_task
from typing import Callable, List, Any, Awaitable, Optional

def map_limited(fn: Callable[[Any], Awaitable[Any]], inputs: List[Any], limit: int) -> List[Any]:
    if limit <= 0:
        raise ValueError("limit must be positive")
    return await gather(*[create_task(fn(input)) for input in inputs[:limit]], return_exceptions=True)

from pathlib import Path, isfile, isdir, join

def image_files(root):
    return sorted(
        join(root, f)
        for f in root.iterdir()
        if isfile(f) and f.suffix.lower() in {".png", ".jpg"}
        and not f.name.lower().endswith(".png") and not f.name.lower().endswith(".jpg")
    )

def top_errors(events, count):
    if count <= 0:
        return []
    error_counts = {}
    for level, message in events:
        if level == "ERROR":
            error_counts[message] = error_counts.get(message, 0) + 1
    return sorted(error_counts.items(), key=lambda x: (-x[1], x[0]))[:count]

def elapsed(start_ns, finish_ns):
    if finish_ns < start_ns:
        raise ValueError("finish precedes start")
    return round((finish_ns - start_ns) / 1e6)

def decode_record(payload):
    import json
    import base64

    try:
        decoded = base64.b64decode(payload)
        decoded = decoded.decode("utf-8")
        decoded = json.loads(decoded)
        if not isinstance(decoded, dict):
            raise ValueError("Record is not a dictionary")
        return decoded["record"]
    except (base64.binascii.Error, json.JSONDecodeError, TypeError, KeyError):
        raise ValueError("Invalid encoding or JSON")

from typing import Iterator, Tuple

def stream_window(stream: Iterator[Tuple[int, T]], start: int, stop: int) -> Iterator[Tuple[int, T]]:
    current_offset = start
    for offset, item in stream:
        if offset >= start and offset < stop:
            yield offset - current_offset, item
        current_offset = offset + 1

def group_updates(updates):
    updates = sorted(updates, key=lambda x: x[0])
    result = {}
    for key, value in updates:
        if key not in result:
            result[key] = []
        result[key].append(value)
    return list(result.items())

def merge_config(base, patch):
    if not isinstance(base, dict) or not isinstance(patch, dict):
        return patch if patch is not None else base
    merged = base.copy()
    for key, value in patch.items():
        if key in merged and isinstance(merged[key], dict) and isinstance(value, dict):
            merged[key] = merge_config(merged[key], value)
        else:
            merged[key] = value
    return merged

