from datetime import datetime

def report_paths(root):
    return sorted((datetime.fromtimestamp(path.stat().st_mtime), path) for path in Path(root).glob("report-*.csv"))

def page_bounds(page, size, total):
    if page <= 0 or size <= 0 or total < 0:
        raise ValueError("page, size, and total must be positive")
    start = page * size
    stop = min(start + size, total)
    return start, stop

from typing import Dict, Tuple, Iterable

def summarize_jobs(jobs: Iterable[Job]) -> Dict[str, Tuple[int, int]]:
    summary = {}
    for job in jobs:
        status = job.status
        size = job.size
        if status in summary:
            summary[status] = (summary[status][0] + 1, summary[status][1] + size)
        else:
            summary[status] = (1, size)
    return {status: (count, total_size) for status, (count, total_size) in summary.items() if total_size != 0}

def retry_read(read, attempts):
    if attempts < 1:
        raise ValueError("attempts must be at least 1")
    for attempt in range(attempts):
        try:
            return read()
        except TimeoutError:
            continue
    raise ValueError("all attempts failed")

from collections import defaultdict

def iter_unique_events(events):
    seen = defaultdict(list)
    for event in events:
        if event.get("id") is not None:
            seen[event["id"]].append(event)
    for id, events in seen.items():
        yield events[0]

def render_row(fields, record, missing="-"):
    escaped_fields = []
    for field in fields:
        if field not in record:
            escaped_fields.append(missing)
        elif record[field] is None:
            escaped_fields.append(str(record[field]))
        elif isinstance(record[field], str):
            escaped_fields.append(record[field].replace("\\", "\\\\").replace("\n", "\\n"))
        else:
            escaped_fields.append(str(record[field]))
    return "\t".join(escaped_fields)
